export function doodle(type='flower'){const shapes={flower:`<g stroke="currentColor" fill="none" stroke-width="2"><path d="M60 100V55M60 80Q25 58 30 78t30 17m0-23q34-30 36-9T60 87"/><g class="flower-petals"><ellipse cx="60" cy="28" rx="9" ry="19"/><ellipse cx="60" cy="28" rx="9" ry="19" transform="rotate(60 60 45)"/><ellipse cx="60" cy="28" rx="9" ry="19" transform="rotate(120 60 45)"/><ellipse cx="60" cy="28" rx="9" ry="19" transform="rotate(180 60 45)"/><ellipse cx="60" cy="28" rx="9" ry="19" transform="rotate(240 60 45)"/><ellipse cx="60" cy="28" rx="9" ry="19" transform="rotate(300 60 45)"/></g><circle cx="60" cy="45" r="8" fill="#e8c451"/></g>`,moon:`<path d="M75 13a46 46 0 1 0 26 72A46 46 0 0 1 75 13Z" fill="#dfb940" stroke="currentColor" stroke-width="2"/><path d="m89 17 3 9 9 3-9 3-3 9-3-9-9-3 9-3Zm-6 40 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="currentColor"/>`,bird:`<path d="m15 70 37-8L40 26l36 25 19-14 13 11-12 7-18 29-25-13-26 15Z" fill="#4f6e9e" stroke="currentColor" stroke-width="2"/><path d="m53 65 23-14-9 24" fill="none" stroke="currentColor"/>`,letter:`<path d="M15 35h90v63H15Z" fill="#e6d7b7" stroke="currentColor" stroke-width="2"/><path d="m15 35 45 36 45-36M15 98l33-36m57 36L72 62" fill="none" stroke="currentColor" stroke-width="2"/><path d="M30 47V15h60v32M41 27h36M41 35h29" fill="#f4eedf" stroke="currentColor" stroke-width="2"/>`,lamp:`<path d="m40 22-18 42h76L80 22ZM60 64v36M40 101h40M48 22v-9h24v9" fill="#e4ba49" stroke="currentColor" stroke-width="2"/><path d="M12 72 4 80m104-8 8 8M60 5V0" stroke="currentColor" stroke-width="2"/>`,box:`<path d="m18 49 42-16 42 16-42 17Zm0 0v39l42 17 42-17V49M60 66v39M17 49l-4-24L55 9l5 24" fill="#c86c45" stroke="currentColor" stroke-width="2"/><path d="M49 77h20v8H49Z" fill="#edcf77" stroke="currentColor"/>`};return `<svg viewBox="0 0 120 120" aria-hidden="true">${shapes[type]||shapes.flower}</svg>`}
